#!/bin/bash -i
#SBATCH --job-name=testassembly
#SBATCH --cpus-per-task=8
#SBATCH --mem=120G
#SBATCH --time=24:00:00
#SBATCH --partition=amd_256M
#SBATCH --output=./masurca.out
#SBATCH --error=./masurca.err

conda activate masurca

echo Start time is `date +%Y/%m/%d--%H:%M`
./assemble.sh
echo Finish time is `date +%Y/%m/%d--%H:%M`

